import{z as i,x as d,o as t,c as p,q as l,j as r,D as E,d as o,s,S as B,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"重链剖分","description":"","frontmatter":{"title":"重链剖分","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/heavy-light.md","filePath":"cs/heavy-light.md","lastUpdated":1791063341000}'),A={name:"cs/heavy-light.md"};function u(D,a,h,m,c,g){const n=d("Mermaid");return t(),p("div",null,[a[2]||(a[2]=l('<h1 id="重链剖分" tabindex="-1">重链剖分 <a class="header-anchor" href="#重链剖分" aria-label="Permalink to &quot;重链剖分&quot;">​</a></h1><div class="epigraph"><p>每条根到叶路径切成 $O(\\log n)$ 条重链；链内 DFS 序连续，路径查询变成序列上 $O(\\log n)$ 段区间。</p><footer>—— 据 Sleator and Tarjan, A Data Structure for Dynamic Trees, 1983 的重边思想；竞赛与教材中的 heavy-light decomposition 整理</footer></div><p>上一课<a href="/cs/tree-binary-lifting">树上倍增与差分</a>处理静态路径和与离线加。线段树、树状数组活在序列上。缺口是把<strong>树上路径</strong>映成序列区间：重链剖分（HLD）。不重写倍增表。本课静态树 + 序列结构；动态换边是 Link-Cut，只点名。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>子树大小 \\(sz[u]\\)。对每个 \\(u\\)，重儿子是 \\(sz\\) 最大的孩子，边 \\((u,\\mathrm{son}[u])\\) 为重边；其余轻边。重边串成重链，链顶 <code>top[u]</code>。性质：任意点到根，轻边次数 \\(O(\\log n)\\)——每次轻边走到的子树至少减半。故任意路径 \\(u\\)–\\(v\\) 可拆成 \\(O(\\log n)\\) 条链上的连续段。</p><p>DFS 先走重儿子，则每条重链在 DFS 序里是连续区间。路径查询：当 <code>top[u]\\neq top[v]</code>，把更深链顶的那一段交给序列结构，再跳到 <code>parent[top]</code>。最后同一链上一段。</p><p>缺口是剖分，不是再发明线段树。</p><p><span class="marginnote">直觉类比：重儿子像家族里继承家业的长子——每代人把占大头的那支血脉（子树节点最多的孩子）连成一条主线，这条主线就是重链；其余孩子另立门户，跨过去就走轻边。</span></p><h3 id="重链不是直径" tabindex="-1">重链不是直径 <a class="header-anchor" href="#重链不是直径" aria-label="Permalink to &quot;重链不是直径&quot;">​</a></h3><p>重边按子树大小，不是边权。直径、最长链是另一回事。Sleator–Tarjan 的动态树用「偏爱边」保持类似重轻，本课静态剖分即可。</p><p><span class="marginnote">HLD 把树路径摊成区间，与 ST 表/线段树对接。Sleator–Tarjan 1983 的 Link-Cut 用 splay 维护优选路径，本课不实现。后课点分治按重心递归，不是按链。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>两遍 DFS：第一遍 \\(sz\\) 与重儿子；第二遍链顶与 DFS 序。路径/子树查询：子树是 DFS 序一段；路径如上跳链。修改同步打到序列结构。</p>',13)),(t(),r(B,null,{default:E(()=>[s(n,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20SZ%5B%22%E5%AD%90%E6%A0%91%E5%A4%A7%E5%B0%8F%22%5D%20--%3E%20HVY%5B%22%E9%87%8D%E5%84%BF%E5%AD%90%20%2F%20%E9%87%8D%E9%93%BE%22%5D%0A%20%20HVY%20--%3E%20SEQ%5B%22DFS%20%E5%BA%8F%E8%BF%9E%E7%BB%AD%22%5D%0A%20%20SEQ%20--%3E%20Q%5B%22%E8%B7%AF%E5%BE%84%20%3D%20O(log%20n)%20%E6%AE%B5%E5%8C%BA%E9%97%B4%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"复杂度：剖分 \\(O(n)\\)；每次路径 \\(O(\\log n)\\) 段乘以序列结构的区间代价（常再 \\(\\log n\\)）。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[o("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"轻边使 \\(sz\\) 减半，故一条根路径上轻边 \\(O(\\log n)\\)，链段数同阶。与倍增比：倍增段数也是 \\(O(\\log n)\\) 但每段是 \\(2^k\\) 祖先跳跃，难接任意区间结构；HLD 的段是真实树边连续，能打懒惰标记。子树修改直接 DFS 序区间，不必走轻边论证。",-1)),a[6]||(a[6]=e("p",null,"路径查询的跳链过程：",-1)),(t(),r(B,null,{default:E(()=>[s(n,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E6%9F%A5%E8%AF%A2%E8%B7%AF%E5%BE%84%20u%E2%80%93v%22%5D%20--%3E%20B%7B%22u%20%E4%B8%8E%20v%20%E7%9A%84%E9%93%BE%E9%A1%B6%E7%9B%B8%E5%90%8C%3F%22%7D%0A%20%20B%20--%20%22%E4%B8%8D%E5%90%8C%22%20--%3E%20C%5B%22%E5%8F%96%E9%93%BE%E9%A1%B6%E6%9B%B4%E6%B7%B1%E7%9A%84%E4%B8%80%E7%AB%AF%E8%AE%B0%E4%B8%BA%20u%22%5D%0A%20%20C%20--%3E%20D%5B%22%E6%8A%8A%20u%20%E5%88%B0%E9%93%BE%E9%A1%B6%E6%98%A0%E6%88%90%E4%B8%80%E6%AE%B5%E5%8C%BA%E9%97%B4%22%5D%0A%20%20D%20--%3E%20E%5B%22u%20%E8%B7%B3%E5%88%B0%E9%93%BE%E9%A1%B6%E7%9A%84%E7%88%B6%E8%8A%82%E7%82%B9%22%5D%0A%20%20E%20--%3E%20B%0A%20%20B%20--%20%22%E7%9B%B8%E5%90%8C%22%20--%3E%20F%5B%22%E5%90%8C%E9%93%BE%E4%B8%8A%E5%8F%96%20u%20%E5%88%B0%20v%20%E7%9A%84%E6%9C%80%E5%90%8E%E4%B8%80%E6%AE%B5%22%5D%0A%20%20F%20--%3E%20G%5B%22%E5%90%84%E6%AE%B5%E5%8C%BA%E9%97%B4%E4%BE%9D%E6%AC%A1%E4%BA%A4%E7%BB%99%E7%BA%BF%E6%AE%B5%E6%A0%91%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<p><span class="marginnote">数字实例：轻边每跨一次，所在子树至少减半，所以 \\(n=100{,}000\\) 的树里任意点到根最多跨 \\(17\\) 条轻边（\\(2^{17} \\gt 10^5\\)）。这就是「路径拆成对数段」的全部来源——不是树浅，是每跳一次问题规模砍半。</span></p><p>不要把「每次跳 <code>top</code>」写成 \\(O(n)\\)：链顶跳跃沿轻边，次数对数。</p><p><span class="marginnote">常见误区：初学者容易以为重链是树上最长的那条链。实际上重边按子树大小选，与边权、直径无关——一条很长的链若每步都只带更小的子树，可能整条都是轻边，剖分时反而被切成一段段。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 LCT、不写欧拉旅游树。点分治处理「过某点的路径统计」，与 HLD 的「路径是区间」不同。后课默认：树上路径可剖成对数段序列区间。下一课用重心把距离类统计变成分治。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>重儿子使轻边减半；路径 \\(O(\\log n)\\) 条链。</li><li>链在 DFS 序连续，接线段树。</li><li>静态剖分；动态树另论。</li><li>出处：重轻思想见 Sleator and Tarjan, 1983；剖分实现为标准教材技法。</li></ul>',7))])}const F=i(A,[["render",u]]);export{f as __pageData,F as default};
